#' Model Fitting and Evaluation Functions
#'
#' Functions for fitting various prediction models and evaluating them
#' using cross-validation or train/test splits.

#' Return the supported model catalog
#'
#' The catalog is the single source of truth for model names, dependencies,
#' outcome types, and broad modeling behavior used by the simulation framework.
#'
#' @param available_only Logical; if TRUE, return only models whose package is
#'   installed in the current R library.
#' @return Data frame describing supported target models.
#' @examples
#' get_model_registry(available_only = TRUE)
#' @export
get_model_registry <- function(available_only = FALSE) {
  registry <- data.frame(
    model = c(
      "lm", "glm", "gam", "ordinal", "lmm", "glmm", "cart", "rf",
      "gbm", "svm", "ridge", "lasso", "nnet"
    ),
    label = c(
      "Linear regression", "Generalized linear model",
      "Generalized additive model", "Proportional-odds ordinal model",
      "Linear mixed model", "Generalized linear mixed model",
      "Classification and regression tree", "Random forest",
      "Gradient-boosted trees", "Support vector machine",
      "Ridge regression", "Lasso regression", "Feed-forward neural network"
    ),
    category = c(
      "statistical", "statistical", "machine_learning", "ordered",
      "mixed_effects", "mixed_effects", "machine_learning",
      "machine_learning", "machine_learning", "machine_learning",
      "regularized", "regularized", "neural_network"
    ),
    outcomes = c(
      "continuous", "continuous, binary, count", "continuous, binary, count",
      "ordered categorical", "continuous", "binary", "continuous, binary",
      "continuous, binary", "continuous, binary", "continuous, binary",
      "continuous", "continuous", "continuous, binary"
    ),
    order_aware = c(
      FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE,
      FALSE, FALSE, FALSE, FALSE
    ),
    neural_network = c(
      FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE,
      FALSE, FALSE, FALSE, TRUE
    ),
    package = c(
      "stats", "stats", "mgcv", "MASS", "lme4", "lme4", "rpart",
      "randomForest", "gbm", "e1071", "glmnet", "glmnet", "nnet"
    ),
    reference_model = c(
      TRUE, TRUE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE,
      FALSE, FALSE, FALSE
    ),
    description = c(
      "Linear effects with a Gaussian outcome.",
      "Automatically selects Gaussian, binomial, or Poisson likelihood.",
      "Smooth nonlinear effects estimated with penalized splines.",
      "Uses the known order of response categories through proportional odds.",
      "Continuous outcomes with random effects supplied in the formula.",
      "Binary outcomes with random effects supplied in the formula.",
      "A single interpretable nonlinear decision tree.",
      "Bagged decision trees for nonlinearities and interactions.",
      "Sequentially boosted trees for nonlinearities and interactions.",
      "Kernel model for nonlinear decision or regression surfaces.",
      "L2-regularized linear regression.",
      "L1-regularized linear regression and variable selection.",
      "One-hidden-layer neural network with configurable regularization."
    ),
    stringsAsFactors = FALSE
  )

  registry$available <- vapply(
    registry$package,
    requireNamespace,
    logical(1),
    quietly = TRUE
  )

  if (available_only) {
    registry <- registry[registry$available, , drop = FALSE]
  }

  rownames(registry) <- NULL
  registry
}

#' Return explicit default tuning parameters for a model
#'
#' @param model_type Character model name or alias.
#' @return Named list of model-specific defaults.
#' @export
get_model_defaults <- function(model_type) {
  model_type <- normalize_model_type(model_type)

  switch(
    model_type,
    lm = list(),
    glm = list(family = NULL),
    gam = list(k = 10, method = "REML", family = NULL),
    ordinal = list(method = "logistic"),
    lmm = list(REML = TRUE),
    glmm = list(family = stats::binomial()),
    cart = list(cp = 0.01, minsplit = 20),
    rf = list(ntree = 500, mtry = NULL, nodesize = NULL),
    gbm = list(
      n.trees = 500, interaction.depth = 3, shrinkage = 0.01,
      n.minobsinnode = 10
    ),
    svm = list(kernel = "radial", cost = 1, gamma = NULL),
    ridge = list(lambda = 0.01),
    lasso = list(lambda = 0.01),
    nnet = list(size = 5, decay = 1e-04, maxit = 200, MaxNWts = 10000),
    stop("Unsupported model type: ", model_type)
  )
}

#' Resolve and validate model tuning parameters
#'
#' @param model_type Character model name or alias.
#' @param model_options Named list overriding defaults.
#' @return Complete named options list.
#' @noRd
resolve_model_options <- function(model_type, model_options = list()) {
  defaults <- get_model_defaults(model_type)
  if (is.null(model_options)) model_options <- list()
  if (!is.list(model_options)) {
    stop("model_options for '", normalize_model_type(model_type), "' must be a list")
  }
  if (length(model_options) > 0 &&
      (is.null(names(model_options)) || any(!nzchar(names(model_options))))) {
    stop("model_options must be a named list")
  }

  unknown <- setdiff(names(model_options), names(defaults))
  if (length(unknown) > 0) {
    stop(
      "Unknown model_options for '", normalize_model_type(model_type), "': ",
      paste(unknown, collapse = ", ")
    )
  }

  modifyList(defaults, model_options)
}

#' Return one model specification from the catalog
#'
#' @param model_type Character model name or alias.
#' @return Named list with catalog fields and default parameters.
#' @export
get_model_spec <- function(model_type) {
  model_type <- normalize_model_type(model_type)
  registry <- get_model_registry()
  idx <- match(model_type, registry$model)
  if (is.na(idx)) stop("Unsupported model type: ", model_type)

  spec <- as.list(registry[idx, , drop = FALSE])
  spec <- lapply(spec, function(x) x[[1]])
  spec$defaults <- get_model_defaults(model_type)
  spec
}

#' Normalize model type to canonical internal name
#'
#' @param model_type Character string specifying model type
#' @return Canonical model type string
#' @noRd
normalize_model_type <- function(model_type) {
  if (is.null(model_type) || length(model_type) != 1 || is.na(model_type)) {
    stop("model_type must be a single non-missing character value")
  }

  normalized <- tolower(trimws(model_type))
  normalized <- gsub("[[:space:]_-]+", "", normalized)

  alias_map <- c(
    lm = "lm",
    glm = "glm",
    rf = "rf",
    randomforest = "rf",
    gbm = "gbm",
    gradientboosting = "gbm",
    gradientboostedmachine = "gbm",
    cart = "cart",
    tree = "cart",
    lmm = "lmm",
    lmer = "lmm",
    glmm = "glmm",
    glmer = "glmm",
    svm = "svm",
    supportvectormachine = "svm",
    ridge = "ridge",
    lasso = "lasso",
    gam = "gam",
    generalizedadditivemodel = "gam",
    ordinal = "ordinal",
    orderedlogit = "ordinal",
    proportionalodds = "ordinal",
    nnet = "nnet",
    neuralnet = "nnet",
    neuralnetwork = "nnet",
    mlp = "nnet"
  )

  if (normalized %in% names(alias_map)) {
    return(unname(alias_map[[normalized]]))
  }

  normalized
}

#' Fit model and evaluate performance
#'
#' @param data Data frame with predictors and outcome
#' @param model_type Character string specifying model type
#' @param response_var Name of response variable
#' @param predictor_vars Vector of predictor variable names
#' @param metrics Character vector of metrics to calculate
#' @param cv_folds Number of cross-validation folds (NULL for train/test split, 0 for in-sample)
#' @param cv_repeats Number of CV repetitions
#' @param model_options Named list of model-specific tuning parameters
#' @param validation_strategy Either "random" or "ordered". Ordered validation
#'   uses earlier observations to predict later observations.
#' @param order_var Optional column used to sort observations before ordered validation.
#' @return List of metric values
#' @details Ordered validation uses expanding training windows and disjoint
#'   subsequent test blocks. It runs once regardless of cv_repeats. Predictors
#'   must be prepared using information available before each forecast origin.
#'   Temporal gaps, overlapping-label purging and grouping are not implemented.
#'   A repeat with failed or nonfinite fold predictions returns missing metrics.
#'   Mixed models require a .group column and use random intercepts.
#' @examples
#' observations <- data.frame(y = sin(1:40), x = 1:40, time = 1:40)
#' fit_and_evaluate_model(observations, "lm", "y", "x", "mse",
#'                        cv_folds = 3, cv_repeats = 1,
#'                        validation_strategy = "ordered", order_var = "time")
#' @export
fit_and_evaluate_model <- function(data, model_type, response_var, predictor_vars,
                                   metrics, cv_folds, cv_repeats,
                                   model_options = list(),
                                   validation_strategy = c("random", "ordered"),
                                   order_var = NULL) {
  validation_strategy <- match.arg(validation_strategy)
  model_type <- normalize_model_type(model_type)
  model_options <- resolve_model_options(model_type, model_options)

  if (!is.data.frame(data) || nrow(data) < 2 ||
      !all(c(response_var, predictor_vars) %in% names(data))) {
    stop("data must have at least two rows and all response/predictor columns")
  }
  if (!is.character(metrics) || !length(metrics) || anyNA(metrics) ||
      any(!metrics %in% supported_metrics())) stop("Unsupported metrics")
  if (length(cv_repeats) != 1 || !is.numeric(cv_repeats) || is.na(cv_repeats) ||
      !is.finite(cv_repeats) || cv_repeats < 1 || cv_repeats != floor(cv_repeats)) {
    stop("cv_repeats must be a positive integer")
  }
  if (!is.null(cv_folds) &&
      (length(cv_folds) != 1 || !is.numeric(cv_folds) || is.na(cv_folds) ||
       !is.finite(cv_folds) || cv_folds < 0 || cv_folds == 1 ||
       cv_folds != floor(cv_folds) || cv_folds >= nrow(data))) {
    stop("cv_folds must be NULL, 0, or an integer from 2 to nrow(data) - 1")
  }
  if (validation_strategy == "ordered" && !is.null(cv_folds) && cv_folds == 0) {
    stop("Ordered validation requires out-of-sample evaluation")
  }

  if (validation_strategy == "ordered") {
    if (!is.null(order_var)) {
      if (!order_var %in% names(data)) {
        stop("order_var not found in data: ", order_var)
      }
      if (anyNA(data[[order_var]])) {
        stop("order_var contains missing values: ", order_var)
      }
      data <- data[order(data[[order_var]]), , drop = FALSE]
    }
    rownames(data) <- NULL
  }

  quote_name <- function(x) paste0("`", gsub("`", "", x, fixed = TRUE), "`")
  formula_text <- paste(quote_name(response_var), "~",
                        paste(quote_name(predictor_vars), collapse = " + "))
  if (model_type %in% c("lmm", "glmm")) {
    if (!".group" %in% names(data)) {
      stop("Mixed models require a .group column for random intercepts")
    }
    formula_text <- paste(formula_text, "+ (1 | .group)")
  }
  formula_obj <- as.formula(formula_text)

  if (is.null(cv_folds)) {
    # Simple train/test split (70/30)
    results <- fit_evaluate_split(
      data, model_type, formula_obj, metrics, response_var,
      in_sample = FALSE, model_options = model_options,
      validation_strategy = validation_strategy
    )
  } else if (cv_folds == 0) {
    # In-sample (apparent) evaluation - train and predict on ALL data
    # WARNING: This gives optimistically biased estimates!
    results <- fit_evaluate_split(
      data, model_type, formula_obj, metrics, response_var,
      in_sample = TRUE, model_options = model_options,
      validation_strategy = validation_strategy
    )
  } else {
    # Cross-validation
    results <- fit_evaluate_cv(
      data, model_type, formula_obj, metrics, cv_folds, cv_repeats,
      response_var, model_options = model_options,
      validation_strategy = validation_strategy
    )
  }

  return(results)
}

#' Train/test split evaluation
#'
#' @param data Data frame
#' @param model_type Character string specifying model type
#' @param formula_obj Formula object
#' @param metrics Character vector of metrics
#' @param response_var Name of response variable
#' @param in_sample Logical: if TRUE, use in-sample (apparent) evaluation
#' @param model_options Complete named model options list
#' @param validation_strategy Either "random" or "ordered"
#' @return List of metric values
#' @noRd
fit_evaluate_split <- function(data, model_type, formula_obj, metrics, response_var,
                               in_sample = FALSE, model_options = list(),
                               validation_strategy = c("random", "ordered")) {
  validation_strategy <- match.arg(validation_strategy)
  n <- nrow(data)
  if (in_sample) {
    # In-sample (apparent) evaluation: train and test on ALL data
    # This gives optimistically biased estimates but matches some published methods
    train_data <- data
    test_data <- data
  } else {
    # Out-of-sample: 70/30 train/test split
    train_size <- floor(0.7 * n)
    train_idx <- if (validation_strategy == "ordered") {
      seq_len(train_size)
    } else {
      sample(seq_len(n), train_size)
    }
    train_data <- data[train_idx, ]
    test_data <- data[-train_idx, ]
  }

  # Fit model
  model <- fit_model(model_type, formula_obj, train_data, model_options)

  # Predict on test data
  predictions <- predict_model(model, model_type, test_data)
  y_true <- numeric_outcome_for_metrics(test_data[[response_var]])

  # Calculate metrics
  metric_values <- calculate_metrics(y_true, predictions, metrics)

  return(metric_values)
}

#' Cross-validation evaluation
#'
#' @param data Data frame
#' @param model_type Character string specifying model type
#' @param formula_obj Formula object
#' @param metrics Character vector of metrics
#' @param cv_folds Number of folds
#' @param cv_repeats Number of repetitions
#' @param response_var Name of response variable
#' @param model_options Complete named model options list
#' @param validation_strategy Either "random" or "ordered"
#' @return List of metric values
#' @noRd
fit_evaluate_cv <- function(data, model_type, formula_obj, metrics, cv_folds,
                            cv_repeats, response_var, model_options = list(),
                            validation_strategy = c("random", "ordered")) {
  validation_strategy <- match.arg(validation_strategy)
  n <- nrow(data)
  if (cv_folds < 2 || cv_folds >= n) {
    stop("cv_folds must be at least 2 and smaller than the number of observations")
  }
  y_true <- numeric_outcome_for_metrics(data[[response_var]])
  effective_repeats <- if (validation_strategy == "ordered") 1L else cv_repeats

  # Store metrics for each repeat (to average metrics, not predictions)
  all_metrics <- list()
  for (metric in metrics) {
    all_metrics[[metric]] <- rep(NA_real_, effective_repeats)
  }

  random_fold_ids <- if (validation_strategy == "random") {
    lapply(seq_len(effective_repeats), function(repeat_index) {
      sample(base::rep(seq_len(cv_folds), length.out = n))
    })
  } else {
    NULL
  }

  for (repeat_index in seq_len(effective_repeats)) {
    predictions <- rep(NA_real_, n)
    fold_errors <- character(0)

    if (validation_strategy == "ordered") {
      # Forward-chaining CV: the first block seeds training, and each later
      # block is predicted only from observations that precede it.
      block_ids <- cut(
        seq_len(n), breaks = cv_folds + 1, labels = FALSE,
        include.lowest = TRUE
      )
      fold_specs <- lapply(seq_len(cv_folds), function(fold) {
        list(train = block_ids <= fold, test = block_ids == fold + 1)
      })
    } else {
      fold_ids <- random_fold_ids[[repeat_index]]
      fold_specs <- lapply(seq_len(cv_folds), function(fold) {
        list(train = fold_ids != fold, test = fold_ids == fold)
      })
    }

    for (fold in seq_along(fold_specs)) {
      train_idx <- fold_specs[[fold]]$train
      test_idx <- fold_specs[[fold]]$test
      train_data <- data[train_idx, , drop = FALSE]
      test_data <- data[test_idx, , drop = FALSE]

      # Fit model
      fold_error <- tryCatch({
        model <- fit_model(model_type, formula_obj, train_data, model_options)

        # Predict
        preds <- predict_model(model, model_type, test_data)
        predictions[test_idx] <- preds
        NULL
      }, error = function(e) {
        paste("Error in fold", fold, "rep", repeat_index, ":", e$message)
      })
      if (!is.null(fold_error)) fold_errors <- c(fold_errors, fold_error)
    }
    if (length(fold_errors)) warning(paste(fold_errors, collapse = "; "), call. = FALSE)

    # Calculate metrics for THIS repeat (not averaged predictions)
    expected_test <- Reduce(`|`, lapply(fold_specs, function(spec) spec$test))
    rep_metrics <- if (any(!is.finite(predictions[expected_test]))) {
      # A failed fold invalidates the repeat; do not score only easier folds.
      stats::setNames(as.list(rep(NA_real_, length(metrics))), metrics)
    } else calculate_metrics(y_true, predictions, metrics)
    for (metric in metrics) {
      all_metrics[[metric]][repeat_index] <- rep_metrics[[metric]]
    }
  }

  # Average metrics across repetitions (not predictions!)
  metric_values <- list()
  for (metric in metrics) {
    values <- all_metrics[[metric]]
    metric_values[[metric]] <- if (all(is.na(values))) NA_real_ else mean(values, na.rm = TRUE)
  }

  return(metric_values)
}

#' Convert outcomes to numeric scores for metric calculation
#'
#' Ordered factors are converted to their rank. Unordered binary factors are
#' mapped to 0/1; other factors use their integer codes.
#'
#' @param y Outcome vector.
#' @return Numeric outcome vector.
#' @noRd
numeric_outcome_for_metrics <- function(y) {
  if (is.ordered(y)) return(as.numeric(y))
  if (is.factor(y)) {
    if (nlevels(y) == 2) return(as.numeric(y) - 1)
    return(as.numeric(y))
  }
  as.numeric(y)
}

#' Fit a model of specified type
#'
#' @param model_type Character string specifying model type
#' @param formula_obj Formula object
#' @param data Training data
#' @param model_options Named list overriding model defaults
#' @return Fitted model object
#' @noRd
fit_model <- function(model_type, formula_obj, data, model_options = list()) {
  model_type <- normalize_model_type(model_type)
  options <- resolve_model_options(model_type, model_options)

  if (model_type == "lm") {
    model <- lm(formula_obj, data = data)

  } else if (model_type == "glm") {
    # Detect family based on response
    response_var <- all.vars(formula_obj)[1]
    y <- data[[response_var]]
    if (!is.null(options$family)) {
      family <- options$family
    } else if (length(unique(y)) == 2) {
      family <- stats::binomial()
    } else if (all(y >= 0) && all(y == floor(y))) {
      family <- stats::poisson()
    } else {
      family <- stats::gaussian()
    }
    model <- glm(formula_obj, data = data, family = family)

  } else if (model_type == "gam") {
    if (!requireNamespace("mgcv", quietly = TRUE)) {
      stop("mgcv package required for generalized additive models")
    }
    response_var <- all.vars(formula_obj)[1]
    predictor_vars <- all.vars(formula_obj)[-1]
    y <- data[[response_var]]

    smooth_terms <- vapply(predictor_vars, function(var_name) {
      x <- data[[var_name]]
      n_unique <- length(unique(x[!is.na(x)]))
      if (is.numeric(x) && n_unique >= 4) {
        k <- max(3, min(as.integer(options$k), n_unique - 1))
        paste0("s(`", var_name, "`, k = ", k, ")")
      } else {
        paste0("`", var_name, "`")
      }
    }, character(1))
    gam_formula <- stats::as.formula(
      paste0("`", response_var, "` ~ ", paste(smooth_terms, collapse = " + ")),
      env = asNamespace("mgcv")
    )

    if (!is.null(options$family)) {
      family <- options$family
    } else if (length(unique(y)) == 2) {
      family <- stats::binomial()
    } else if (all(y >= 0) && all(y == floor(y))) {
      family <- stats::poisson()
    } else {
      family <- stats::gaussian()
    }
    model <- mgcv::gam(
      gam_formula, data = data, family = family, method = options$method
    )

  } else if (model_type == "ordinal") {
    if (!requireNamespace("MASS", quietly = TRUE)) {
      stop("MASS package required for proportional-odds ordinal models")
    }
    response_var <- all.vars(formula_obj)[1]
    y <- data[[response_var]]
    observed <- y[!is.na(y)]
    if (!is.ordered(y)) {
      ordered_levels <- if (is.factor(y)) {
        levels(y)
      } else if (is.numeric(observed)) {
        sort(unique(observed))
      } else {
        unique(as.character(observed))
      }
      data[[response_var]] <- ordered(y, levels = ordered_levels)
    }
    if (nlevels(data[[response_var]]) < 3) {
      stop("ordinal models require an ordered outcome with at least three levels")
    }
    model <- MASS::polr(
      formula_obj, data = data, method = options$method, Hess = FALSE,
      model = TRUE
    )

  } else if (model_type == "rf") {
    if (!requireNamespace("randomForest", quietly = TRUE)) {
      stop("randomForest package required")
    }
    # Ensure binary outcomes are treated as classification, not regression.
    response_var <- all.vars(formula_obj)[1]
    y <- data[[response_var]]
    if (length(unique(y)) == 2) {
      data[[response_var]] <- as.factor(y)
    }
    rf_args <- list(
      formula = formula_obj,
      data = data,
      ntree = options$ntree
    )
    if (!is.null(options$mtry)) rf_args$mtry <- options$mtry
    if (!is.null(options$nodesize)) rf_args$nodesize <- options$nodesize
    model <- do.call(randomForest::randomForest, rf_args)

  } else if (model_type == "gbm") {
    if (!requireNamespace("gbm", quietly = TRUE)) {
      stop("gbm package required")
    }
    # Convert formula to gbm format
    response <- all.vars(formula_obj)[1]
    is_binary <- length(unique(data[[response]])) == 2
    distribution <- if (is_binary) "bernoulli" else "gaussian"
    model <- gbm::gbm(
      formula_obj, data = data, distribution = distribution,
      n.trees = options$n.trees,
      interaction.depth = options$interaction.depth,
      shrinkage = options$shrinkage,
      n.minobsinnode = options$n.minobsinnode,
      cv.folds = 0, verbose = FALSE
    )

  } else if (model_type == "cart" || model_type == "tree") {
    if (!requireNamespace("rpart", quietly = TRUE)) {
      stop("rpart package required for CART")
    }
    response_var <- all.vars(formula_obj)[1]
    y <- data[[response_var]]
    method <- if (length(unique(y)) == 2) "class" else "anova"
    if (method == "class") data[[response_var]] <- as.factor(y)
    model <- rpart::rpart(
      formula_obj, data = data, method = method,
      control = rpart::rpart.control(cp = options$cp, minsplit = options$minsplit)
    )

  } else if (model_type == "lmm" || model_type == "lmer") {
    if (!requireNamespace("lme4", quietly = TRUE)) {
      stop("lme4 package required for mixed models")
    }
    # Assumes formula already includes random effects
    model <- lme4::lmer(formula_obj, data = data, REML = options$REML)

  } else if (model_type == "glmm" || model_type == "glmer") {
    if (!requireNamespace("lme4", quietly = TRUE)) {
      stop("lme4 package required for mixed models")
    }
    model <- lme4::glmer(formula_obj, data = data, family = options$family)

  } else if (model_type == "svm") {
    if (!requireNamespace("e1071", quietly = TRUE)) {
      stop("e1071 package required for SVM")
    }
    svm_args <- list(
      formula = formula_obj, data = data,
      kernel = options$kernel, cost = options$cost
    )
    if (!is.null(options$gamma)) svm_args$gamma <- options$gamma
    model <- do.call(e1071::svm, svm_args)

  } else if (model_type == "ridge") {
    if (!requireNamespace("glmnet", quietly = TRUE)) {
      stop("glmnet package required for ridge regression")
    }
    response_var <- all.vars(formula_obj)[1]
    predictor_vars <- all.vars(formula_obj)[-1]
    X <- as.matrix(data[, predictor_vars, drop = FALSE])
    y <- data[[response_var]]
    model <- glmnet::glmnet(X, y, alpha = 0)  # alpha = 0 for ridge
    attr(model, "codefunction_lambda") <- options$lambda

  } else if (model_type == "lasso") {
    if (!requireNamespace("glmnet", quietly = TRUE)) {
      stop("glmnet package required for lasso regression")
    }
    response_var <- all.vars(formula_obj)[1]
    predictor_vars <- all.vars(formula_obj)[-1]
    X <- as.matrix(data[, predictor_vars, drop = FALSE])
    y <- data[[response_var]]
    model <- glmnet::glmnet(X, y, alpha = 1)  # alpha = 1 for lasso
    attr(model, "codefunction_lambda") <- options$lambda

  } else if (model_type == "nnet") {
    if (!requireNamespace("nnet", quietly = TRUE)) {
      stop("nnet package required for neural-network models")
    }
    response_var <- all.vars(formula_obj)[1]
    y <- data[[response_var]]
    is_binary <- length(unique(y[!is.na(y)])) == 2
    if (is_binary) data[[response_var]] <- as.factor(y)

    nnet_args <- list(
      formula = formula_obj,
      data = data,
      size = options$size,
      decay = options$decay,
      maxit = options$maxit,
      MaxNWts = options$MaxNWts,
      trace = FALSE
    )
    if (!is_binary) nnet_args$linout <- TRUE
    model <- do.call(nnet::nnet, nnet_args)
    attr(model, "codefunction_binary") <- is_binary

  } else {
    stop("Unsupported model type: ", model_type)
  }

  return(model)
}

#' Make predictions from fitted model
#'
#' @param model Fitted model object
#' @param model_type Character string specifying model type
#' @param newdata New data for predictions
#' @return Numeric vector of predictions
#' @noRd
predict_model <- function(model, model_type, newdata) {
  model_type <- normalize_model_type(model_type)

  tryCatch({
    if (model_type == "gbm") {
      # Use optimal number of trees (or default to n.trees)
      n_trees <- ifelse(!is.null(model$n.trees), model$n.trees, 500)
      preds <- predict(model, newdata = newdata, n.trees = n_trees, type = "response")

    } else if (model_type == "rf") {
      if (!is.null(model$type) && model$type == "classification") {
        prob_matrix <- predict(model, newdata = newdata, type = "prob")
        if (!is.matrix(prob_matrix)) {
          stop("Random forest classification predictions did not return probabilities")
        }

        class_names <- colnames(prob_matrix)
        if (!is.null(class_names) && "1" %in% class_names) {
          preds <- prob_matrix[, "1", drop = TRUE]
        } else {
          preds <- prob_matrix[, ncol(prob_matrix), drop = TRUE]
        }
      } else {
        preds <- predict(model, newdata = newdata)
      }
      preds <- as.numeric(preds)

    } else if (model_type == "cart" && identical(model$method, "class")) {
      prob_matrix <- predict(model, newdata = newdata, type = "prob")
      class_names <- colnames(prob_matrix)
      if (!is.null(class_names) && "1" %in% class_names) {
        preds <- prob_matrix[, "1", drop = TRUE]
      } else {
        preds <- prob_matrix[, ncol(prob_matrix), drop = TRUE]
      }
      preds <- as.numeric(preds)

    } else if (model_type %in% c("glm", "gam")) {
      preds <- predict(model, newdata = newdata, type = "response")

    } else if (model_type == "ordinal") {
      prob_matrix <- predict(model, newdata = newdata, type = "probs")
      if (is.null(dim(prob_matrix))) {
        probability_names <- names(prob_matrix)
        prob_matrix <- matrix(prob_matrix, nrow = 1)
        colnames(prob_matrix) <- probability_names
      }
      # Ordinal metrics use category ranks, not the numeric spelling of labels.
      class_scores <- seq_len(ncol(prob_matrix))
      preds <- drop(prob_matrix %*% class_scores)

    } else if (model_type %in% c("ridge", "lasso")) {
      # Extract predictor variables
      predictor_vars <- rownames(model$beta)
      X_new <- as.matrix(newdata[, predictor_vars, drop = FALSE])
      requested_lambda <- attr(model, "codefunction_lambda")
      if (is.null(requested_lambda)) requested_lambda <- 0.01
      lambda_idx <- which.min(abs(model$lambda - requested_lambda))
      preds <- predict(model, newx = X_new, s = model$lambda[lambda_idx])
      preds <- as.numeric(preds)

    } else if (model_type == "nnet") {
      raw_preds <- predict(model, newdata = newdata, type = "raw")
      if (is.matrix(raw_preds)) {
        class_names <- colnames(raw_preds)
        if (!is.null(class_names) && "1" %in% class_names) {
          preds <- raw_preds[, "1", drop = TRUE]
        } else {
          preds <- raw_preds[, ncol(raw_preds), drop = TRUE]
        }
      } else {
        preds <- raw_preds
      }
      preds <- as.numeric(preds)

    } else if (model_type %in% c("lmm", "lmer", "glmm", "glmer")) {
      preds <- predict(model, newdata = newdata, re.form = NA, type = "response")

    } else {
      preds <- predict(model, newdata = newdata)
    }

    return(preds)
  }, error = function(e) {
    warning(paste("Prediction error:", e$message))
    return(rep(NA_real_, nrow(newdata)))
  })
}

#' Get model type from fitted object
#'
#' @param model Fitted model object
#' @return Character string with model type
#' @noRd
get_model_type <- function(model) {
  if (inherits(model, "gam")) {
    return("gam")
  } else if (inherits(model, "polr")) {
    return("ordinal")
  } else if (inherits(model, "nnet")) {
    return("nnet")
  } else if (inherits(model, "lm") && !inherits(model, "glm")) {
    return("lm")
  } else if (inherits(model, "glm")) {
    return("glm")
  } else if (inherits(model, "randomForest")) {
    return("rf")
  } else if (inherits(model, "gbm")) {
    return("gbm")
  } else if (inherits(model, "rpart")) {
    return("cart")
  } else if (inherits(model, "lmerMod")) {
    return("lmm")
  } else if (inherits(model, "glmerMod")) {
    return("glmm")
  } else {
    return("unknown")
  }
}
